823: fn strip_comments_and_directives(text: &str) -> String {
824:     let bytes = text.as_bytes();
825:     let mut out = String::with_capacity(text.len());
826:     let mut i = 0usize;
827:     let mut in_line_comment = false;
828:     let mut in_block_comment = false;
829:     let mut in_string: Option<u8> = None;
830:     while i < bytes.len() {
831:         let b = bytes[i];
832:         let next = bytes.get(i + 1).copied();
833:         if in_line_comment {
834:             if b == b'\n' {
835:                 in_line_comment = false;
836:                 out.push('\n');
837:             } else {
838:                 out.push(' ');
839:             }
840:             i += 1;
841:             continue;
842:         }
843:         if in_block_comment {
844:             if b == b'*' && next == Some(b'/') {
845:                 out.push_str("  ");
846:                 in_block_comment = false;
847:                 i += 2;
848:             } else {
849:                 out.push(if b == b'\n' { '\n' } else { ' ' });
850:                 i += 1;
851:             }
852:             continue;
853:         }
854:         if let Some(quote) = in_string {
855:             out.push(b as char);
856:             if b == b'\\' && next.is_some() {
857:                 i += 1;
858:                 out.push(bytes[i] as char);
859:             } else if b == quote {
860:                 in_string = None;
861:             }
862:             i += 1;
863:             continue;
864:         }
865:         if (b == b'"' || b == b'\'') && !in_line_comment && !in_block_comment {
866:             in_string = Some(b);
867:             out.push(b as char);
868:             i += 1;
869:             continue;
870:         }
871:         if b == b'/' && next == Some(b'/') {
872:             in_line_comment = true;
873:             out.push_str("  ");
874:             i += 2;
875:             continue;
876:         }
877:         if b == b'/' && next == Some(b'*') {
878:             in_block_comment = true;
879:             out.push_str("  ");
880:             i += 2;
881:             continue;
882:         }
883:         out.push(b as char);
884:         i += 1;
885:     }
886: 
887:     out.lines()
888:         .map(|line| {
889:             if line.trim_start().starts_with('#') {
890:                 ""
891:             } else {
892:                 line
893:             }
894:         })
895:         .collect::<Vec<_>>()
896:         .join("\n")
897: }
