1963: fn function_base_name(name: &str) -> String {
1964:     let before_params = name.split_once('(').map_or(name, |(head, _)| head).trim();
1965:     before_params
1966:         .split_whitespace()
1967:         .last()
1968:         .unwrap_or(before_params)
1969:         .trim()
1970:         .to_string()
1971: }
